#define main oldmain
#include "coordinate_integrate.cpp"
#undef main
#include <quadmath.h>
#include <boost/multiprecision/cpp_dec_float.hpp>
using MP=boost::multiprecision::cpp_dec_float_100;
template<class T>T sqrtt(T x){using std::sqrt;return sqrt(x);}template<>__float128 sqrtt(__float128 x){return sqrtq(x);}
template<class T>T logt(T x){using std::log;return log(x);}template<>__float128 logt(__float128 x){return logq(x);}
template<class T>T expt(T x){using std::exp;return exp(x);}template<>__float128 expt(__float128 x){return expq(x);}
struct OptTerm{vector<array<int,3>>e;};
struct OG{Graph g;vector<OptTerm>terms;};
struct Sec{int masks[28],bmax[6];LD alpha[6];};
Sec sector(const OG&g,int L,const array<unsigned char,8>&vp,const array<unsigned char,8>&gp,LD rate){int n=L+1,pos[8],rank[7],minr[28];for(int j=0;j<n;j++)pos[vp[j]]=j;for(int j=0;j<L;j++)rank[gp[j]]=j;Sec s{};int k=0;for(int a=0;a<n;a++)for(int b=a+1;b<n;b++){int lo=min(pos[a],pos[b]),hi=max(pos[a],pos[b]),mask=0;for(int j=lo;j<hi;j++)mask|=1<<rank[j];s.masks[k]=mask;minr[k]=__builtin_ctz(mask);k++;}for(auto&t:g.terms){int bs[6]={};for(auto&e:t.e)for(int j=0;j<minr[e[0]];j++)bs[j]+=e[1];for(int j=0;j<L-1;j++)s.bmax[j]=max(s.bmax[j],bs[j]);}for(int j=0;j<L-1;j++){LD p=L-1-j-s.bmax[j]/2.L;if(p<0)throw runtime_error("power in free graph");s.alpha[j]=rate*max(.5L,p);}return s;}
template<class T>array<T,7> point(const OG&g,int L,int K,const Sec&s,const LD*logtvals,LD*rat){int D=L-1,sz=1<<L;T gap[7];gap[0]=1;T weight=1;for(int j=0;j<D;j++){T tt=expt(T(logtvals[j]));gap[j+1]=gap[j]*tt;weight*=expt(T((D-j-s.alpha[j])*logtvals[j]))/T(s.alpha[j]);}T dist[128]={},iv[28],logs[28];for(int mask=1;mask<sz;mask++){int bit=__builtin_ctz(mask);dist[mask]=dist[mask^(1<<bit)]+gap[bit];}int NE=L*(L+1)/2;for(int k=0;k<NE;k++){iv[k]=1/sqrtt(dist[s.masks[k]]);logs[k]=logt(dist[s.masks[k]])/2;}array<T,7>sum{};T absum[7]={};for(auto&t:g.terms){T H=0,R=0,base=1,lv=0;for(auto&e:t.e){int k=e[0],m=e[1];H+=m*dist[s.masks[k]];R+=e[2]*dist[s.masks[k]];T v=iv[k];if(m==1)base*=v;else if(m==2)base*=v*v;else base*=v*v*v;lv+=m*logs[k];}if(R==0)continue;base*=R/H;lv-=L*logt(H);for(int j=0;j<=K;j++){sum[j]+=base;absum[j]+=base<0?-base:base;base*=lv/(j+1);}}if(rat){*rat=1;for(int j=0;j<=K;j++)if(absum[j]>0)*rat=min(*rat,abs((LD)(sum[j]/absum[j])));}for(int j=0;j<=K;j++)sum[j]*=weight;return sum;}
int main(int argc,char**argv){try{if(argc<9){cerr<<"root L points reps seed net output rate [select]\n";return 1;}string root=argv[1];int L=stoi(argv[2]),N=stoi(argv[3]),B=stoi(argv[4]);uint64_t seed=stoull(argv[5]);string netfile=argv[6],output=argv[7];LD rate=stold(argv[8]);string sel=argc>9?argv[9]:"free";int Li;auto g0=load(root+"/L"+to_string(L)+"_coord.txt",Li);vector<OG>gs;int NE=L*(L+1)/2;for(auto&g:g0){OG og;og.g=g;for(auto&t:g.terms){OptTerm tt;for(int k=0;k<NE;k++)if(t.m[k])tt.e.push_back({k,t.m[k],t.co[k]});og.terms.push_back(tt);}gs.push_back(move(og));}vector<int>counts(gs.size(),N);if(argc>10){ifstream cf(argv[10]);int nn;cf>>nn;if(nn!=(int)gs.size())throw runtime_error("counts mismatch");for(int i=0;i<nn;i++){int id,k;cf>>id>>k;counts[id]=k;}if(!cf)throw runtime_error("counts file");}vector<LD>gam(7);ifstream gf(root+"/cgamma_L"+to_string(L)+".txt");for(auto&x:gam)gf>>x;
 ifstream nf(netfile,ios::binary);uint32_t hdr[3];nf.read((char*)hdr,12);int dim=hdr[1],bits=hdr[2];if(hdr[0]!=(uint32_t)B||dim<L+1)throw runtime_error("net dims");vector<uint64_t>mat((size_t)B*dim*bits);nf.read((char*)mat.data(),mat.size()*8);if(!nf)throw runtime_error("netfile");auto vps=perms(L+1,true),gps=perms(L,false);LD norm=(L%2)?1:-1;for(int i=2;i<=L+1;i++)norm*=i;for(int i=2;i<=L;i++)norm*=i;int K=7-L;vector<vector<LD>>batches(B,vector<LD>(14));vector<vector<array<LD,14>>>per(B,vector<array<LD,14>>(gs.size()));vector<long long>quads(B),mps(B);double start=omp_get_wtime();
 #pragma omp parallel for num_threads(4) schedule(dynamic)
 for(int ib=0;ib<B;ib++){const uint64_t*dir=&mat[(size_t)ib*dim*bits];for(int gi=0;gi<(int)gs.size();gi++){auto&g=gs[gi];int NN=counts[gi];if(!NN)continue;if(g.g.power||g.terms.empty())continue;if(L==7&&abs(3*g.g.wb-g.g.wa)<1e-17L)continue;if(sel=="primitive"&&!g.g.primitive)continue;if(sel=="nonprimitive"&&g.g.primitive)continue;mt19937_64 rng(seed+0x9e3779b97f4a7c15ULL*(ib+1)+0xbf58476d1ce4e5b9ULL*(gi+1));vector<uint64_t>state(dim);for(auto&v:state)v=rng()&((1ULL<<bits)-1);array<LD,7>tot{};for(int it=0;it<NN;it++){if(it){int z=__builtin_ctz(it);for(int j=0;j<dim;j++)state[j]^=dir[j*bits+z];}LD uu[16];for(int j=0;j<dim;j++)uu[j]=((LD)state[j]+.5L)/powl(2.L,bits);auto s=sector(g,L,vps[min((size_t)(uu[0]*vps.size()),vps.size()-1)],gps[min((size_t)(uu[1]*gps.size()),gps.size()-1)],rate);LD lt[6];for(int j=0;j<L-1;j++)lt[j]=logl(uu[j+2])/s.alpha[j];LD ratio;auto val=point<LD>(g,L,K,s,lt,&ratio);if(ratio<1e-7L){quads[ib]++;auto q=point<__float128>(g,L,K,s,lt,&ratio);for(int k=0;k<=K;k++)val[k]=(LD)q[k];if(ratio<1e-24L){mps[ib]++;auto m=point<MP>(g,L,K,s,lt,nullptr);for(int k=0;k<=K;k++)val[k]=(LD)m[k];}}for(int j=0;j<=K;j++)tot[j]+=val[j]/NN;}
 for(int k=0;k<=K;k++){LD val=0;for(int j=0;j<=k;j++)val+=tot[j]*gam[k-j];int i=L-1+k;per[ib][gi][i]=norm*g.g.wa*val;per[ib][gi][7+i]=norm*g.g.wb*val;batches[ib][i]+=per[ib][gi][i];batches[ib][7+i]+=per[ib][gi][7+i];}}
 #pragma omp critical
 cerr<<"rep "<<ib<<" seconds "<<omp_get_wtime()-start<<" b0 "<<setprecision(16)<<batches[ib][L-1]<<" c0 "<<batches[ib][7+L-1]<<" q "<<quads[ib]<<" mp "<<mps[ib]<<"\n";}
 ofstream out(output);out<<setprecision(24)<<"{\"L\":"<<L<<",\"N\":"<<N<<",\"replicates\":"<<B<<",\"seed\":"<<seed<<",\"rate\":"<<rate<<",\"selection\":\""<<sel<<"\",\"seconds\":"<<omp_get_wtime()-start<<",\"batches\":[";for(int ib=0;ib<B;ib++){if(ib)out<<',';out<<'[';for(int j=0;j<14;j++){if(j)out<<',';out<<batches[ib][j];}out<<']';}out<<"],\"graph_batches\":[";for(int ib=0;ib<B;ib++){if(ib)out<<',';out<<'[';for(int gi=0;gi<(int)gs.size();gi++){if(gi)out<<',';out<<'[';for(int j=0;j<14;j++){if(j)out<<',';out<<per[ib][gi][j];}out<<']';}out<<']';}out<<"],\"counts\":[";for(int gi=0;gi<(int)counts.size();gi++){if(gi)out<<',';out<<counts[gi];}out<<"],\"quads\":[";for(int ib=0;ib<B;ib++){if(ib)out<<',';out<<quads[ib];}out<<"],\"mps\":[";for(int ib=0;ib<B;ib++){if(ib)out<<',';out<<mps[ib];}out<<"]}\n";
 }catch(exception&e){cerr<<e.what()<<'\n';return 2;}}
